import random

def generate_sales_report(products):
    # Simulate sales data
    sales_data = {product: [random.randint(1, 100) for _ in range(10)] for product in products}

    # Simulate profit data
    profit_data = {product: [random.uniform(1, 10) for _ in range(10)] for product in products}

    # Calculate total sales and profit for each product
    total_sales = {product: sum(sales) for product, sales in sales_data.items()}
    total_profit = {product: sum(profit) for product, profit in profit_data.items()}

    # Combine sales and profit data
    report_data = {
        product: {
            'total_sales': total_sales[product],
            'total_profit': total_profit[product]
        }
        for product in products
    }

    # Sort the report by total profit in descending order
    sorted_report = sorted(report_data.items(), key=lambda x: x[1]['total_profit'], reverse=True)

    # Format the report
    report = []
    for product, data in sorted_report:
        report.append(f"Product: {product}")
        report.append(f"Total Sales: {data['total_sales']}")
        report.append(f"Total Profit: {data['total_profit']}")
        report.append("")

    return "\n".join(report)

# Example usage
products = ['Product A', 'Product B', 'Product C', 'Product D']
report = generate_sales_report(products)
print(report)
```

