Here's a self-contained Python function that uses NumPy to simulate pet shop sales with a Poisson-distributed number of customers. Each customer buys one animal randomly chosen from the provided list. The function prints a readable summary and returns a dictionary containing the total number of customers and the counts per animal.

```python
def simulate_pet_shop_sales(animals, mu, seed=None, probs=None):
    """
    Simulate pet shop sales.

    Parameters:
    - animals: list of animal names (e.g., ['dog', 'cat', 'fish'])
    - mu: mean of the Poisson distribution for the number of customers (lambda)
    - seed: optional integer seed for reproducibility
    - probs: optional list of probabilities for each animal (must sum > 0 and match len(animals)).
             If None, animals are chosen uniformly.

    Returns:
    A dict: {
        'total_customers': int,
        'sales': {animal_name: count, ...}
    }

    Requires: numpy (for RNG and Poisson sampling)
    """
    import numpy as np
    from collections import Counter

    # Basic validation
    if not isinstance(animals, (list, tuple)) or len(animals) == 0:
        raise ValueError("animals must be a non-empty list or tuple of names.")
    if mu is None or mu < 0:
        raise ValueError("mu must be a non-negative number (mean of Poisson).")
    if probs is not None:
        if not isinstance(probs, (list, tuple)) or len(probs) != len(animals):
            raise ValueError("probs must be a list with the same length as animals.")
        probs_arr = np.array(probs, dtype=float)
        if np.any(probs_arr < 0):
            raise ValueError("probs must contain non-negative values.")
        if probs_arr.sum() == 0:
            raise ValueError("probs must sum to a positive value.")
        probs_arr = probs_arr / probs_arr.sum()
        probs_to_use = probs_arr.tolist()
    else:
        probs_to_use = None

    rng = np.random.default_rng(seed)
    n_customers = int(rng.poisson(lam=mu))

    if n_customers == 0:
        sales_counts = {a: 0 for a in animals}
        print(f"No customers today (Poisson draw with mu={mu} resulted in 0).")
    else:
        purchases = rng.choice(animals, size=n_customers, p=probs_to_use)
        counter = Counter(purchases)
        sales_counts = {a: int(counter.get(a, 0)) for a in animals}

        print(f"Total customers: {n_customers}")
        for a in animals:
            print(f"  {a}: {sales_counts[a]}")

    summary = {'total_customers': n_customers, 'sales': sales_counts}
    return summary

# Example usage:
# summary = simulate_pet_shop_sales(['dog', 'cat', 'fish'], mu=4.5, seed=42)
# print(summary)
```

