def most_common_words_from_json_dir(
    dir_path,
    top_n=20,
    recursive=False,
    min_word_length=2,
    extra_stopwords=None,
    encoding="utf-8",
):
    """
    Read all .json files in dir_path, extract all textual content, and return the top_n most frequent words
    with their counts.

    External dependency: nltk (for tokenization and stopword list).
    If nltk data packages 'punkt' and 'stopwords' are not available, they will be downloaded automatically.

    Parameters:
    - dir_path (str): path to the directory containing .json files
    - top_n (int): number of most common words to return (default 20)
    - recursive (bool): whether to search subdirectories recursively (default False)
    - min_word_length (int): minimum length of token to consider (default 2)
    - extra_stopwords (iterable of str or None): additional stopwords to exclude
    - encoding (str): file encoding to use when opening JSON files (default "utf-8")

    Returns:
    - List[Tuple[str, int]]: list of (word, count) sorted by descending frequency

    Notes:
    - The function extracts all string values from JSON structures (including nested lists/dicts).
    - Tokens are lower-cased. Non-letter characters are removed from tokens before filtering.
    - Tokens containing digits are ignored.
    - JSON files that cannot be parsed are skipped with a warning.
    """
    import os
    import json
    import re
    import warnings
    from collections import Counter

    # External library
    try:
        import nltk
        from nltk.corpus import stopwords
        from nltk.tokenize import word_tokenize
    except Exception as e:
        raise ImportError(
            "This function requires the 'nltk' package. Install it with `pip install nltk`. "
            "Original error: {}".format(e)
        )

    # Ensure necessary nltk data is available
    try:
        nltk.data.find("tokenizers/punkt")
    except LookupError:
        nltk.download("punkt", quiet=True)
    try:
        nltk.data.find("corpora/stopwords")
    except LookupError:
        nltk.download("stopwords", quiet=True)

    # Build stopword set
    sw = set(stopwords.words("english"))
    if extra_stopwords:
        sw.update(w.lower() for w in extra_stopwords)

    # Collect JSON file paths
    json_paths = []
    if recursive:
        for root, _, files in os.walk(dir_path):
            for fname in files:
                if fname.lower().endswith(".json"):
                    json_paths.append(os.path.join(root, fname))
    else:
        try:
            for fname in os.listdir(dir_path):
                if fname.lower().endswith(".json"):
                    json_paths.append(os.path.join(dir_path, fname))
        except FileNotFoundError:
            raise FileNotFoundError(f"Directory not found: {dir_path}")

    if not json_paths:
        return []

    # Recursive extractor for strings from arbitrary JSON objects
    def extract_strings(obj):
        if obj is None:
            return
        if isinstance(obj, str):
            yield obj
        elif isinstance(obj, dict):
            for v in obj.values():
                yield from extract_strings(v)
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                yield from extract_strings(item)
        else:
            # ignore numbers, booleans, etc.
            return

    token_counter = Counter()
    non_letter_re = re.compile(r"[^A-Za-z']+")  # keep letters and apostrophes for better tokens
    digit_re = re.compile(r"\d")

    for path in json_paths:
        try:
            with open(path, "r", encoding=encoding) as f:
                data = json.load(f)
        except Exception as e:
            warnings.warn(f"Skipping '{path}' (could not read/parse JSON): {e}")
            continue

        # Extract all string pieces
        for text_piece in extract_strings(data):
            # Tokenize using nltk
            try:
                tokens = word_tokenize(text_piece)
            except Exception:
                # Fallback naive split if tokenization fails
                tokens = text_piece.split()

            for tok in tokens:
                # Remove surrounding non-letters, keep apostrophes inside words (e.g., "don't" -> dont or don't depending)
                cleaned = non_letter_re.sub("", tok)
                if not cleaned:
                    continue
                # ignore tokens containing digits
                if digit_re.search(cleaned):
                    continue
                cleaned_l = cleaned.lower()
                if len(cleaned_l) < max(1, min_word_length):
                    continue
                if cleaned_l in sw:
                    continue
                token_counter[cleaned_l] += 1

    return token_counter.most_common(top_n)

# Example usage:
# top_words = most_common_words_from_json_dir("/path/to/json_dir", top_n=30, recursive=True)
