import os
import shutil
from pathlib import Path
from typing import Dict
import openpyxl

def protect_quotes_in_xlsx(dir_path: str, recursive: bool = False, backup: bool = True) -> Dict[str, int]:
    """
    Finds all .xlsx files in the given directory (optionally recursively) and
    prefixes every double-quote character (") inside text cell values with a
    double backslash (\\). Formula cells (values starting with '=') are skipped
    to avoid corrupting formulas.

    Parameters:
    - dir_path: path to the directory containing .xlsx files
    - recursive: if True, search subdirectories recursively (default False)
    - backup: if True, create a timestamped backup copy for each modified file (default True)

    Returns:
    A dict mapping each processed file path (string) to the number of cells modified in that file.
    Requires the external library 'openpyxl' (pip install openpyxl).
    """
    dirp = Path(dir_path).expanduser()
    if not dirp.is_dir():
        raise ValueError(f"Directory does not exist: {dir_path}")

    pattern = "**/*.xlsx" if recursive else "*.xlsx"
    results: Dict[str, int] = {}

    for file_path in dirp.glob(pattern):
        # Ensure we only handle files (skip directories that match pattern for some reason)
        if not file_path.is_file():
            continue

        try:
            wb = openpyxl.load_workbook(file_path)
        except Exception as e:
            # skip files that can't be opened as workbooks
            # (corrupted, encrypted, in-use, not actually xlsx, etc.)
            print(f"Skipping {file_path}: cannot open workbook ({e})")
            continue

        modified_count = 0
        try:
            for ws in wb.worksheets:
                # iterate over all cells in worksheet (returns tuples of Cell objects)
                for row in ws.iter_rows():
                    for cell in row:
                        val = cell.value
                        # Only operate on plain strings; skip None and other types.
                        if isinstance(val, str):
                            # Skip formula cells to avoid breaking formulas
                            if val.startswith('='):
                                continue
                            if '"' in val:
                                # Insert two backslashes before each double quote
                                new_val = val.replace('"', '\\\\' + '"')
                                if new_val != val:
                                    cell.value = new_val
                                    modified_count += 1
        finally:
            if modified_count > 0:
                # create backup if requested
                if backup:
                    # make a simple backup with .bak and a numeric suffix if needed
                    bak_path = file_path.with_suffix(file_path.suffix + ".bak")
                    # if exists, append counter
                    if bak_path.exists():
                        counter = 1
                        while True:
                            candidate = file_path.with_suffix(file_path.suffix + f".bak{counter}")
                            if not candidate.exists():
                                bak_path = candidate
                                break
                            counter += 1
                    try:
                        shutil.copy2(file_path, bak_path)
                    except Exception as e:
                        print(f"Warning: could not create backup for {file_path}: {e}")

                try:
                    wb.save(file_path)
                except Exception as e:
                    print(f"Error saving {file_path}: {e}")
                finally:
                    try:
                        wb.close()
                    except Exception:
                        pass
                results[str(file_path)] = modified_count
            else:
                # nothing changed; close workbook and continue
                try:
                    wb.close()
                except Exception:
                    pass

        # end processing file

    return results
