```python
import random
import string

def replace_random_substring(strings):
    def generate_random_string(length):
        return ''.join(random.choices(string.ascii_lowercase, k=length))

    def replace_substring(s):
        # Find all substrings between commas or at the beginning/end of the string
        substrings = []
        start = 0
        while start < len(s):
            if s[start] == ',':
                end = s.find(',', start + 1)
                if end == -1:
                    end = len(s)
                substrings.append(s[start:end])
                start = end + 1
            else:
                end = s.find(',', start)
                if end == -1:
                    end = len(s)
                substrings.append(s[start:end])
                start = end + 1

        # Replace each substring with a random string of the same length
        for i, substring in enumerate(substrings):
            random_string = generate_random_string(len(substring))
            s = s.replace(substring, random_string)

        return s

    return [replace_substring(s) for s in strings]

# Example usage:
strings = [
    "hello,world,python",
    "this,is,a,test",
    "random,string,example"
]

modified_strings = replace_random_substring(strings)
for s in modified_strings:
    print(s)
```

