def compare_csv_files(file1_path: str, file2_path: str, 
                     primary_key: List[str] = None, 
                     ignore_columns: List[str] = None) -> List[Dict[str, Any]]:
    """
    Compare two CSV files and generate a detailed difference report.

    Args:
        file1_path (str): Path to the first CSV file
        file2_path (str): Path to the second CSV file
        primary_key (List[str], optional): Column names to use as primary key for matching rows.
                                          If None, uses line numbers for comparison.
        ignore_columns (List[str], optional): Column names to ignore during comparison.

    Returns:
        List[Dict[str, Any]]: List of difference records, each containing:
            - line_number: The line number(s) where difference occurred
            - status: 'ADDED', 'REMOVED', or 'MODIFIED'
            - content: The content of the line(s) or specific field differences
    """
    def read_csv_file(file_path: str) -> List[Dict[str, str]]:
        """Read CSV file and return list of dictionaries."""
        with open(file_path, 'r', encoding='utf-8') as file:
            reader = csv.DictReader(file)
            return list(reader)

    def create_row_key(row: Dict[str, str], key_columns: List[str]) -> str:
        """Create a unique key for a row based on specified columns."""
        if not key_columns:
            return None
        return '|'.join(str(row.get(col, '')) for col in key_columns)

    # Read both CSV files
    try:
        data1 = read_csv_file(file1_path)
        data2 = read_csv_file(file2_path)
    except FileNotFoundError as e:
        raise FileNotFoundError(f"File not found: {e}")
    except Exception as e:
        raise Exception(f"Error reading CSV files: {e}")

    # Get column names (excluding ignored columns)
    if data1:
        all_columns = list(data1[0].keys())
        if ignore_columns:
            compare_columns = [col for col in all_columns if col not in ignore_columns]
        else:
            compare_columns = all_columns
    else:
        compare_columns = []

    differences = []

    if primary_key:
        # Compare using primary key matching
        dict1 = {}
        dict2 = {}

        # Create dictionaries with primary keys
        for i, row in enumerate(data1, 1):
            key = create_row_key(row, primary_key)
            if key:
                dict1[key] = (i, row)

        for i, row in enumerate(data2, 1):
            key = create_row_key(row, primary_key)
            if key:
                dict2[key] = (i, row)

        # Find added rows (in file2 but not in file1)
        for key in dict2:
            if key not in dict1:
                line_num2, row2 = dict2[key]
                differences.append({
                    'line_number': f"File2:{line_num2}",
                    'status': 'ADDED',
                    'content': row2
                })

        # Find removed rows (in file1 but not in file2)
        for key in dict1:
            if key not in dict2:
                line_num1, row1 = dict1[key]
                differences.append({
                    'line_number': f"File1:{line_num1}",
                    'status': 'REMOVED',
                    'content': row1
                })

        # Find modified rows
        for key in dict1:
            if key in dict2:
                line_num1, row1 = dict1[key]
                line_num2, row2 = dict2[key]

                # Check if any compared columns differ
                modified_fields = {}
                for col in compare_columns:
                    if row1.get(col) != row2.get(col):
                        modified_fields[col] = {
                            'old_value': row1.get(col),
                            'new_value': row2.get(col)
                        }

                if modified_fields:
                    differences.append({
                        'line_number': f"File1:{line_num1}, File2:{line_num2}",
                        'status': 'MODIFIED',
                        'content': modified_fields
                    })

    else:
        # Compare by line number (simple line-by-line comparison)
        max_lines = max(len(data1), len(data2))

        for i in range(max_lines):
            line_num = i + 1

            if i < len(data1) and i < len(data2):
                # Both files have this line
                row1 = data1[i]
                row2 = data2[i]

                # Check if any compared columns differ
                modified_fields = {}
                for col in compare_columns:
                    if row1.get(col) != row2.get(col):
                        modified_fields[col] = {
                            'old_value': row1.get(col),
                            'new_value': row2.get(col)
                        }

                if modified_fields:
                    differences.append({
                        'line_number': line_num,
                        'status': 'MODIFIED',
                        'content': modified_fields
                    })

            elif i < len(data1):
                # Row exists only in file1
                differences.append({
                    'line_number': line_num,
                    'status': 'REMOVED',
                    'content': data1[i]
                })

            elif i < len(data2):
                # Row exists only in file2
                differences.append({
                    'line_number': line_num,
                    'status': 'ADDED',
                    'content': data2[i]
                })

    return differences

# Example usage and demonstration
def print_difference_report(differences: List[Dict[str, Any]]):
    """Print a formatted difference report."""
    if not differences:
        print("No differences found!")
        return

    print(f"\nDifference Report ({len(differences)} differences found):")
    print("-" * 80)

    for i, diff in enumerate(differences, 1):
        print(f"\n{i}. Line: {diff['line_number']}")
        print(f"   Status: {diff['status']}")

        if diff['status'] == 'MODIFIED':
            print("   Changed fields:")
            for field, values in diff['content'].items():
                print(f"     {field}: '{values['old_value']}' → '{values['new_value']}'")
        else:
            print("   Content:")
            for key, value in diff['content'].items():
                print(f"     {key}: {value}")

# Example usage
if __name__ == "__main__":
