def get_github_user_ascii(username, token=None, timeout=10):
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Dependencies:
      - requests (pip install requests)
      - Unidecode (pip install Unidecode)

    Parameters:
      - username (str): GitHub username to look up.
      - token (str, optional): Personal access token to increase rate limits (passed in Authorization header).
      - timeout (int or float, optional): Request timeout in seconds.

    Returns:
      - dict: The JSON response from the GitHub API with all string data transliterated to ASCII.

    Raises:
      - ValueError: If username is empty or user not found (404).
      - RuntimeError: For network or other HTTP errors.
    """
    if not username or not isinstance(username, str):
        raise ValueError("username must be a non-empty string")

    # Local imports so this is self-contained as a single function body.
    try:
        import requests
    except Exception as e:
        raise RuntimeError("The 'requests' library is required. Install with: pip install requests") from e
    try:
        from unidecode import unidecode
    except Exception as e:
        raise RuntimeError("The 'Unidecode' library is required. Install with: pip install Unidecode") from e

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    try:
        resp = requests.get(url, headers=headers, timeout=timeout)
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Network error while contacting GitHub API: {e}") from e

    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    if not resp.ok:
        # Try to include message from GitHub if present
        try:
            info = resp.json()
            msg = info.get("message", resp.text)
        except Exception:
            msg = resp.text
        raise RuntimeError(f"GitHub API error {resp.status_code}: {msg}")

    try:
        data = resp.json()
    except ValueError as e:
        raise RuntimeError("Failed to decode JSON response from GitHub API") from e

    # Recursive normalization function
    def normalize(obj):
        # Strings -> transliterate to ASCII
        if isinstance(obj, str):
            return unidecode(obj)
        # Bytes -> decode (utf-8 with replacement) then transliterate
        if isinstance(obj, (bytes, bytearray)):
            try:
                s = obj.decode("utf-8", errors="replace")
            except Exception:
                s = str(obj)
            return unidecode(s)
        # Mappings/dicts -> normalize keys and values
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                # JSON keys are strings, but ensure ascii keys too
                key_str = unidecode(str(k))
                new[key_str] = normalize(v)
            return new
        # Lists/tuples -> normalize each element, preserve type for tuple
        if isinstance(obj, list):
            return [normalize(i) for i in obj]
        if isinstance(obj, tuple):
            return tuple(normalize(i) for i in obj)
        # Other JSON primitives (int, float, bool, None) -> return as-is
        return obj

    normalized = normalize(data)
    return normalized

