# user_info = get_github_user_ascii("torvalds")
# print(user_info["name"])

Here's a self-contained Python function using spaCy that removes the last word from a sentence, POS-tags the remaining text, and returns counts of the POS tags (excluding punctuation and whitespace). It will raise a clear error if the specified spaCy model isn't installed.

You can copy and paste this into a script. Install spaCy and the small English model if needed:
pip install spacy
python -m spacy download en_core_web_sm

```python
from collections import Counter
from functools import lru_cache
from typing import Dict
import spacy

@lru_cache(maxsize=1)
def _load_spacy_model(model_name: str):
    try:
        return spacy.load(model_name)
    except OSError as e:
        raise RuntimeError(
            f"spaCy model '{model_name}' is not installed. Install it with:\n"
            f"    python -m spacy download {model_name}"
        ) from e

def count_pos_without_last(sentence: str, model_name: str = "en_core_web_sm", tag_type: str = "pos") -> Dict[str, int]:
    """
    Count POS tags in `sentence` after removing the last word.

    - sentence: input string.
    - model_name: spaCy model to use (default "en_core_web_sm").
    - tag_type: "pos" for universal POS tags (token.pos_), or "tag" for detailed tags (token.tag_).

    Returns a dict mapping tag -> count (only counts non-punctuation, non-space tokens).
    """
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")

    if tag_type not in ("pos", "tag"):
        raise ValueError("tag_type must be 'pos' or 'tag'")

    nlp = _load_spacy_model(model_name)
    doc = nlp(sentence)

    # Find the last token that is a "word" (not punctuation or space)
    last_word_token = None
    for token in reversed(doc):
        if not token.is_punct and not token.is_space:
            last_word_token = token
            break

    # If there's no word token (empty or only punctuation), nothing to count
    if last_word_token is None:
        return {}

    # Build text keeping all tokens except the last word token (preserving spacing/punctuation)
    kept_text = "".join(t.text_with_ws for t in doc if t.i != last_word_token.i).strip()
    if not kept_text:
        return {}

    doc_trunc = nlp(kept_text)

    # Count POS tags for non-punct, non-space tokens
    if tag_type == "pos":
        tags = (t.pos_ for t in doc_trunc if not t.is_punct and not t.is_space)
    else:
        tags = (t.tag_ for t in doc_trunc if not t.is_punct and not t.is_space)

    return dict(Counter(tags))

# Example:
# print(count_pos_without_last("The quick brown fox jumps over the lazy dog."))
# Might output: {'DET': 2, 'ADJ': 3, 'NOUN': 2, 'VERB': 1, 'ADP': 1}
```

If you want the function to also count punctuation tokens or to treat numbers differently, I can adjust the token filtering.

Here's a self-contained Python function that uses the standard-library external module collections.Counter to calculate the mode(s) of all elements in a nested list L (handles arbitrarily nested lists/tuples). The function returns a tuple (modes, count) where modes is a list of the most frequent element(s) in their original form and count is the occurrence count.

```python
from collections import Counter
from typing import Any, Dict, Tuple, List

def mode_of_nested(L: Any) -> Tuple[List[Any], int]:
    """
    Calculate the mode(s) of all elements in a nested list/tuple structure L.

    Returns:
        (modes, count) where:
            - modes is a list of the element(s) with the highest frequency (in original form),
            - count is the integer frequency of those mode element(s).

    Raises:
        ValueError if there are no elements in L.

    Examples:
        mode_of_nested([1, [2, 2, [3, 1]], 1]) -> ([1], 3)
        mode_of_nested([[1,2],[2,1]]) -> ([1, 2], 2)  # ties returned as a list
    """
    def make_hashable(x: Any) -> Any:
        """Convert x into a hashable representation suitable as a dictionary key."""
        # simple immutable primitives: leave as-is
        if isinstance(x, (str, bytes, int, float, bool, type(None))):
            return x
        # lists and tuples -> tuple of hashable elements
        if isinstance(x, (list, tuple)):
            return tuple(make_hashable(e) for e in x)
        # sets -> sorted tuple with a marker so it's distinct from tuples
        if isinstance(x, set):
            return ('__set__', tuple(sorted(make_hashable(e) for e in x)))
        # dicts -> sorted tuple of (key, value) pairs with marker
        if isinstance(x, dict):
            return ('__dict__', tuple(sorted((make_hashable(k), make_hashable(v)) for k, v in x.items())))
        # fallback: if already hashable, use as-is; otherwise use repr
        try:
            hash(x)
            return x
        except TypeError:
            return ('__repr__', repr(x))

    def flatten_and_count(obj: Any, counter: Counter, representatives: Dict[Any, Any]) -> None:
        """Recursively traverse lists/tuples and count non-container elements."""
        if isinstance(obj, (list, tuple)):
            for item in obj:
                flatten_and_count(item, counter, representatives)
        else:
            key = make_hashable(obj)
            if key not in representatives:
                representatives[key] = obj  # store original representative
            counter[key] += 1

    counter = Counter()
    representatives: Dict[Any, Any] = {}
    flatten_and_count(L, counter, representatives)

    if not counter:
        raise ValueError("No elements found in input (empty nested structure).")

    max_count = max(counter.values())
    modes = [representatives[k] for k, v in counter.items() if v == max_count]
    return modes, max_count
```

Usage:
- Call mode_of_nested(your_nested_list). It returns (modes_list, count). If there's a single most frequent element, modes_list will have length 1.

import pandas as pd

def most_common_per_column(csv_path_or_buffer):
    """
    Read a CSV (must have a header) and return a dict mapping each column name
    to its most common value. If multiple values tie for most common, the
    alphabetically first value is chosen. An empty CSV returns an empty dict.

    The function accepts a file path or any file-like object readable by pandas.read_csv.
    Requires: pandas
    """
    try:
        # Read everything as strings and treat empty fields as empty strings (not NaN)
        df = pd.read_csv(csv_path_or_buffer, dtype=str, keep_default_na=False)
    except pd.errors.EmptyDataError:
        return {}

    if df.empty or df.columns.size == 0:
        return {}

    result = {}
    for col in df.columns:
        vc = df[col].value_counts()  # counts of each distinct string value
        if vc.empty:
            # No values in column (shouldn't happen with keep_default_na=False, but be safe)
            continue
        max_count = vc.iloc[0]
        # values that have the maximum count
        tied_values = [val for val, cnt in vc.items() if cnt == max_count]
        tied_values.sort()  # alphabetical tie-breaker
        result[col] = tied_values[0]

    return result

# Example:
# >>> most_common_per_column("data.csv")
# {'name': 'Alice', 'city': 'Boston'}

def task_func(points):
    """
    Calculate Euclidean distances between consecutive 2D points.

    - points: iterable of items where each item is
        * a scalar (int/float) -> interpreted as (v, v)
        * a 1-length sequence (e.g. (v,) or [v]) -> interpreted as (v, v)
        * a 2+ length sequence -> first two elements taken as (x, y)
    - Returns a list of distances between consecutive points.
    - If len(points) < 2, returns [].

    Example:
    >>> task_func([(1, 2), (4), (-1.2, 4)])
    [3.605551275463989, 5.2]
    """
    import numpy as np

    if not points or len(points) < 2:
        return []

    def to_point(p):
        if isinstance(p, str):
            raise ValueError("String is not a valid point representation.")
        if np.isscalar(p):
            v = float(p)
            return np.array([v, v], dtype=float)
        try:
            seq = list(p)
        except TypeError:
            # Not iterable, attempt to treat as scalar
            v = float(p)
            return np.array([v, v], dtype=float)
        if len(seq) == 0:
            raise ValueError("Empty sequence is not a valid point.")
        if len(seq) == 1:
            v = float(seq[0])
            return np.array([v, v], dtype=float)
        # Take first two elements as coordinates
        return np.array([float(seq[0]), float(seq[1])], dtype=float)

    pts = [to_point(pt) for pt in points]
    distances = [float(np.linalg.norm(pts[i + 1] - pts[i])) for i in range(len(pts) - 1)]
    return distances

Here's a self-contained Python function that uses NumPy to compute mean, sum, max, min and standard deviation for keys "x", "y", and "z" from a list of dictionaries. It filters out missing and non-numeric values and returns a dictionary of results (includes count and allows ddof choice for std):

```python
from typing import List, Dict, Any, Optional

def summarize_xyz(d: List[Dict[str, Any]], ddof: int = 0) -> Dict[str, Dict[str, Optional[float]]]:
    """
    Calculate mean, sum, max, min and standard deviation for keys "x", "y", "z"
    from a list of dictionaries `d`, using NumPy.

    Parameters:
    - d: list of dicts possibly containing numeric values for keys "x","y","z"
    - ddof: degrees of freedom for standard deviation (default 0 => population std)

    Returns:
    A dict like:
    {
      "x": {"count": int, "mean": float|None, "sum": float|None, "max": float|None, "min": float|None, "std": float|None},
      "y": {...},
      "z": {...}
    }
    Values are None for stats when no valid numeric entries exist for that key.
    """
    import numpy as np

    keys = ("x", "y", "z")
    result: Dict[str, Dict[str, Optional[float]]] = {}

    for key in keys:
        vals = []
        for item in d:
            if not isinstance(item, dict):
                continue
            if key not in item:
                continue
            v = item[key]
            # try to coerce to float and skip NaN/non-numeric
            try:
                fv = float(v)
            except (TypeError, ValueError):
                continue
            if np.isnan(fv):
                continue
            vals.append(fv)

        if len(vals) == 0:
            result[key] = {"count": 0, "mean": None, "sum": None, "max": None, "min": None, "std": None}
        else:
            arr = np.array(vals, dtype=float)
            result[key] = {
                "count": int(arr.size),
                "mean": float(np.mean(arr)),
                "sum": float(np.sum(arr)),
                "max": float(np.max(arr)),
                "min": float(np.min(arr)),
                "std": float(np.std(arr, ddof=ddof)),
            }

    return result

# Example:
# d = [{"x": 1, "y": 2}, {"x": 3, "y": 4, "z": 5}, {"x": None, "z": 7}, {"x": "6"}]
# print(summarize_xyz(d))
```

You can change ddof to 1 if you want sample standard deviation instead of population standard deviation.

def count_xyz_values(d):
    """
    Count occurrences of values for keys "x", "y" and "z" in a list of dictionaries `d`.
    Returns a dict mapping each key to a dict of value->count, e.g.
      { "x": {"a": 3, "b": 1}, "y": {"foo": 2}, "z": {} }
    Uses the external library pandas.

    Raises:
      ImportError if pandas is not installed.
      TypeError if `d` is not a list/tuple of dict-like objects.
    """
    try:
        import pandas as pd
    except ImportError as e:
        raise ImportError("This function requires pandas. Install with: pip install pandas") from e

    if not isinstance(d, (list, tuple)):
        raise TypeError("d must be a list or tuple of dictionaries")

    # Create DataFrame from list of dicts (missing keys become NaN and are ignored by value_counts)
    df = pd.DataFrame(d)

    result = {}
    for key in ("x", "y", "z"):
        if key in df.columns:
            # value_counts() ignores NaN by default
            vc = df[key].value_counts()
            # convert counts to plain Python ints
            result[key] = {val: int(count) for val, count in vc.items()}
        else:
            result[key] = {}

    return result

