import pandas as pd

def count_key_values(d, keys=('x', 'y', 'z')):
    """
    Count occurrences of values for specified keys in a list of dicts.

    Parameters:
      d (list of dict): input list of dictionaries
      keys (iterable): keys to count values for (default ('x','y','z'))

    Returns:
      dict: mapping each key to a dict of value -> count
