def extract_and_plot_json_numbers(json_data, path, plot='hist', bins=30,
                                  figsize=(8, 5), title=None, xlabel=None, ylabel=None,
                                  save_path=None, show=True, return_fig=False):
    """
    Extract numerical values from a nested JSON-like structure and visualize them.

    Parameters
    - json_data: dict/list or a JSON string containing the data.
    - path: a path describing how to reach the numbers. Can be:
        - list/tuple of keys (e.g. ['users', '*', 'age'])
        - dot-separated string (e.g. 'users.*.age')
        Use '*' to mean "all elements" at that level (works for lists and dicts).
        Numeric strings like '0' will be treated as list indices when applicable.
    - plot: one of 'hist', 'line', 'box', 'bar' (default 'hist').
    - bins: number of bins for histogram (default 30).
    - figsize: tuple for figure size.
    - title, xlabel, ylabel: optional labels for the plot.
    - save_path: if provided, save the figure to this path (e.g. 'out.png').
    - show: whether to call plt.show() (default True).
    - return_fig: if True, return the matplotlib Figure object as well as the list of numbers.

    Returns
    - values: list of numeric values extracted.
    - fig (optional): matplotlib.figure.Figure if return_fig True.

    Notes
    - Booleans are excluded (they are subclasses of int).
    - If the path ends before reaching scalar values, the function will collect all numeric
      leaves under the current subtree.

    Example usage:
    data = {
        "users": [
            {"name": "A", "age": 30, "scores": [10, 20]},
            {"name": "B", "age": 25, "scores": [15, 25]}
        ]
    }
    # extract ages:
    vals = extract_and_plot_json_numbers(data, 'users.*.age', plot='bar')
    """
    import json
    import numbers
    try:
        import matplotlib.pyplot as plt
    except Exception as e:
        raise RuntimeError("matplotlib is required for plotting. Install it and try again.") from e

    # parse json_data if it's a string
    if isinstance(json_data, str):
        json_obj = json.loads(json_data)
    else:
        json_obj = json_data

    # normalize path into list of parts
    if isinstance(path, (list, tuple)):
        parts = list(path)
    elif isinstance(path, str):
        # allow empty string -> whole object
        parts = [p for p in path.split('.') if p != ''] if path != '' else []
    else:
        raise TypeError("path must be a list/tuple of keys or a dot-separated string")

    values = []

    def collect_all_numbers(node):
        """Recursively collect any numeric leaves under node."""
        if isinstance(node, numbers.Number) and not isinstance(node, bool):
            values.append(node)
        elif isinstance(node, dict):
            for v in node.values():
                collect_all_numbers(v)
        elif isinstance(node, (list, tuple)):
            for item in node:
                collect_all_numbers(item)
        # else: ignore non-numeric scalars (str, None, bool, etc.)

    def traverse(node, parts_remaining):
        if not parts_remaining:
            # end of path: collect numeric leaves under node
            collect_all_numbers(node)
            return

        part = parts_remaining[0]
        rest = parts_remaining[1:]

        # wildcard: iterate all items if list or values if dict
        if part == '*':
            if isinstance(node, dict):
                for v in node.values():
                    traverse(v, rest)
            elif isinstance(node, (list, tuple)):
                for item in node:
                    traverse(item, rest)
            else:
                # cannot expand wildcard on scalar
                return
        else:
            # try dict access first
            if isinstance(node, dict):
                if part in node:
                    traverse(node[part], rest)
                else:
                    # missing key: nothing to do
                    return
            elif isinstance(node, (list, tuple)):
                # try integer index
                idx = None
                try:
                    idx = int(part)
                except Exception:
                    idx = None

                if idx is not None:
                    # index access if in bounds
                    if 0 <= idx < len(node):
                        traverse(node[idx], rest)
                    else:
                        return
                else:
                    # possibly each element is dict and has this key; try applying to each element
                    for elem in node:
                        if isinstance(elem, dict) and part in elem:
                            traverse(elem[part], rest)
                    # if elements are not dicts or key missing, nothing happens
            else:
                # scalar -> cannot traverse further
                return

    traverse(json_obj, parts)

    if not values:
        raise ValueError("No numeric values found for the given path.")

    # plotting
    fig = plt.figure(figsize=figsize)
    ax = fig.add_subplot(1, 1, 1)

    # Title/labels defaulting
    if title:
        ax.set_title(title)
    if xlabel:
        ax.set_xlabel(xlabel)
    if ylabel:
        ax.set_ylabel(ylabel)

    if plot == 'hist':
        ax.hist(values, bins=bins, color='C0', edgecolor='black')
        if xlabel is None:
            ax.set_xlabel('Value')
        if ylabel is None:
            ax.set_ylabel('Frequency')
    elif plot == 'box':
        ax.boxplot(values, vert=True, patch_artist=True,
                   boxprops=dict(facecolor='C0', color='black'))
        if xlabel is None:
            ax.set_xlabel('')
        if ylabel is None:
            ax.set_ylabel('Value')
    elif plot == 'line':
        ax.plot(range(len(values)), values, marker='o', linestyle='-')
        if xlabel is None:
            ax.set_xlabel('Index')
        if ylabel is None:
            ax.set_ylabel('Value')
    elif plot == 'bar':
        ax.bar(range(len(values)), values, color='C0')
        if xlabel is None:
            ax.set_xlabel('Index')
        if ylabel is None:
            ax.set_ylabel('Value')
    else:
        plt.close(fig)
        raise ValueError("Unsupported plot type. Choose from 'hist', 'box', 'line', 'bar'.")

    plt.tight_layout()

    if save_path:
        fig.savefig(save_path)

    if show:
        plt.show()
    else:
        # close if not showing to avoid resource leak in non-interactive contexts
        plt.close(fig)

    if return_fig:
        return values, fig
    return values

def html_table_to_sqlite(
    source,
    db_path="data.db",
    table_name=None,
    selector=None,
    if_exists="replace",
    pk=None,
    timeout=10,
    encoding=None,
):
    """
    Parse an HTML table from a URL or local file and store it in an SQLite database.

    Parameters
    - source (str): URL (http/https) or local file path containing HTML.
    - db_path (str): Path to SQLite database file to create/use.
    - table_name (str|None): Name for the created table. If None, a name is generated.
    - selector (int|str|None): If int -> index of table on page (0-based).
                                If str -> CSS selector to find table(s).
                                If None -> first <table> element is used.
    - if_exists (str): 'replace' (drop/create), 'append' (append rows), or 'fail' (error if table exists).
    - pk (str|list|None): column name or list of names to set as primary key (optional).
    - timeout (int): HTTP request timeout in seconds (only for URLs).
    - encoding (str|None): If reading a local file, explicit encoding (e.g. 'utf-8'). If None, use default.

    Returns a dict with:
    - table (str): final table name
    - columns (list): list of (column_name, sqlite_type) tuples
    - rows_inserted (int): number of rows inserted

    Notes:
    - Requires external libraries: requests, beautifulsoup4
      Install with: pip install requests beautifulsoup4
    - This function handles basic tables; complex rowspan/colspan behavior is not fully addressed.
    - SQLite type inference is conservative (INTEGER, REAL, TEXT).
    """

    # Imports placed inside function so this is self-contained if pasted into a script
    import sqlite3
    import re
    from urllib.parse import urlparse

    try:
        import requests
    except Exception as e:
        raise RuntimeError("This function requires the 'requests' package. Install with 'pip install requests'") from e

    try:
        from bs4 import BeautifulSoup
    except Exception as e:
        raise RuntimeError("This function requires the 'beautifulsoup4' package. Install with 'pip install beautifulsoup4'") from e

    # ---- Helper utilities ----
    def _is_url(s):
        p = urlparse(s)
        return p.scheme in ("http", "https")

    def _sanitize_colname(name):
        # Lowercase, replace non-alnum with underscore, collapse underscores, ensure not empty.
        n = re.sub(r"\s+", " ", name.strip())
        n = re.sub(r"[^0-9a-zA-Z]+", "_", n)
        n = re.sub(r"_+", "_", n)
        n = n.strip("_")
        if not n:
            n = "col"
        # ensure doesn't start with digit (not required by sqlite but nicer)
        if re.match(r"^\d", n):
            n = "c_" + n
        return n.lower()

    def _try_int(s):
        try:
            if re.fullmatch(r"[+-]?\d+", s):
                return int(s)
        except Exception:
            pass
        return None

    def _try_float(s):
        try:
            if re.fullmatch(r"[+-]?(\d+\.\d*|\.\d+)([eE][+-]?\d+)?|[+-]?\d+[eE][+-]?\d+", s):
                return float(s)
        except Exception:
            pass
        return None

    def _infer_sqlite_type(values):
        # values: list of raw strings or None
        # Return "INTEGER", "REAL", or "TEXT"
        has_text = False
        has_real = False
        has_int = False
        for v in values:
            if v is None or v == "":
                continue
            s = str(v).strip()
            if s == "":
                continue
            if _try_int(s) is not None:
                has_int = True
                continue
            if _try_float(s) is not None:
                has_real = True
                continue
            has_text = True
            break
        if has_text:
            return "TEXT"
        if has_real and not has_text:
            return "REAL"
        if has_int and not has_real and not has_text:
            return "INTEGER"
        # default
        return "TEXT"

    # ---- Fetch HTML ----
    if _is_url(source):
        try:
            resp = requests.get(source, timeout=timeout)
            resp.raise_for_status()
            html = resp.content
            # requests will guess encoding when accessing resp.text; but we pass bytes to BS for best behavior
        except Exception as e:
            raise RuntimeError(f"Failed to fetch URL {source!r}: {e}") from e
    else:
        # local file
        try:
            mode = "rb"
            with open(source, mode) as f:
                html = f.read()
        except Exception as e:
            raise RuntimeError(f"Failed to read local file {source!r}: {e}") from e

    # ---- Parse with BeautifulSoup ----
    # prefer lxml if available, otherwise html.parser
    parser = "lxml"
    try:
        soup = BeautifulSoup(html, parser)
    except Exception:
        soup = BeautifulSoup(html, "html.parser")

    # Find tables
    found_tables = []
    if selector is None:
        found_tables = soup.find_all("table")
    elif isinstance(selector, int):
        found_tables = soup.find_all("table")
        # if index out of range, handle later
    elif isinstance(selector, str):
        # css selector => try soup.select
        try:
            found_tables = soup.select(selector)
        except Exception:
            # fallback to find by id or name
            t = soup.find("table", {"id": selector}) or soup.find("table", {"name": selector})
            found_tables = [t] if t is not None else []
    else:
        raise ValueError("selector must be None, an int (index) or a CSS selector string")

    if isinstance(selector, int):
        idx = selector
        if idx < 0 or idx >= len(found_tables):
            raise IndexError(f"No table at index {idx}. {len(found_tables)} table(s) found.")
        table_el = found_tables[idx]
    else:
        if not found_tables:
            raise ValueError("No <table> elements found for the given selector/source.")
        # If the selector matched many tables, pick the first
        table_el = found_tables[0]

    # ---- Extract header and rows ----
    def _extract_text(cell):
        # collapse whitespace and strip
        return " ".join(cell.get_text(separator=" ", strip=True).split())

    # Get rows
    rows = []
    for tr in table_el.find_all("tr"):
        # only consider direct td/th children (ignore nested tables)
        cells = tr.find_all(["td", "th"])
        # skip empty rows
        if not cells:
            continue
        row = [_extract_text(c) for c in cells]
        rows.append(row)

    if not rows:
        raise ValueError("No table rows found in selected table.")

    # Determine header row: prefer thead or first row with <th>
    header_row = None
    start_idx = 0
    thead = table_el.find("thead")
    if thead:
        # use first tr in thead
        thr = thead.find("tr")
        if thr:
            ths = thr.find_all(["th", "td"])
            if ths:
                header_row = [_extract_text(c) for c in ths]
                # build data rows from table rows excluding thead rows
                # Rebuild rows by traversing tbody/tr outside thead to preserve order
                data_rows = []
                for tr in table_el.find_all("tr"):
                    if tr.find_parent("thead"):
                        continue
                    tds = tr.find_all(["td", "th"])
                    if not tds:
                        continue
                    # skip if this is exactly the header we used (rare)
                    if [_extract_text(c) for c in tds] == header_row:
                        continue
                    data_rows.append([_extract_text(c) for c in tds])
                rows = data_rows
    if header_row is None:
        # look for first row with any th
        for i, tr in enumerate(table_el.find_all("tr")):
            if tr.find("th"):
                header_row = [_extract_text(c) for c in tr.find_all(["th", "td"])]
                # remove this row from rows
                # remove matching first occurrence in rows
                for j, r in enumerate(rows):
                    if r == header_row:
                        start_idx = j + 1
                        break
                break
    if header_row is None:
        # fallback: use first row as header
        header_row = rows[0]
        start_idx = 1
        rows = rows[start_idx:]
    else:
        # ensure rows reflect skipping header row we've identified (if start_idx not set)
        # if start_idx not explicitly found, try to drop first identical row
        if start_idx == 0 and rows and rows[0] == header_row:
            rows = rows[1:]

    # Normalize column count: some rows may have different cell counts
    max_cols = max(len(header_row), *(len(r) for r in rows))
    # pad header and rows to max_cols with empty string
    header_row = header_row + [f"col{idx}" for idx in range(len(header_row), max_cols)]
    new_rows = []
    for r in rows:
        if len(r) < max_cols:
            r = r + [""] * (max_cols - len(r))
        elif len(r) > max_cols:
            r = r[:max_cols]
        new_rows.append(r)
    rows = new_rows

    # Sanitize header names and ensure uniqueness
    sanitized = []
    seen = {}
    for i, h in enumerate(header_row):
        name = _sanitize_colname(h or f"col_{i+1}")
        if name in seen:
            seen[name] += 1
            name = f"{name}_{seen[name]}"
        else:
            seen[name] = 0
        sanitized.append(name)

    # If no table_name was provided, generate one from source
    if not table_name:
        base = "html_table"
        if _is_url(source):
            parsed = urlparse(source)
            host = re.sub(r"[^0-9a-zA-Z]+", "_", parsed.netloc) or "site"
            base = f"{host}_table"
        else:
            import os

            bn = os.path.basename(source) or "file"
            bn = re.sub(r"[^0-9a-zA-Z]+", "_", bn)
            base = f"{bn}_table"
        # ensure uniqueness by appending a numeric suffix if needed
        table_name = base

    # Connect to sqlite
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()

    try:
        # check existing
        cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name=?;", (table_name,)
        )
        exists = cur.fetchone() is not None

        if exists:
            if if_exists == "fail":
                raise RuntimeError(f"Table {table_name!r} already exists in {db_path}.")
            if if_exists == "replace":
                cur.execute(f"DROP TABLE IF EXISTS \"{table_name}\";")
                conn.commit()
                exists = False
            # if 'append', we keep exists True

        # infer column types by sampling column values (use all rows; user can refine later)
        cols_values = [[] for _ in sanitized]
        for r in rows:
            for i, v in enumerate(r):
                val = v.strip() if isinstance(v, str) else (v if v is not None else "")
                cols_values[i].append(val)

        col_types = [_infer_sqlite_type(vals) for vals in cols_values]

        if not exists:
            # create table
            parts = []
            for name, typ in zip(sanitized, col_types):
                parts.append(f"\"{name}\" {typ}")
            if pk:
                if isinstance(pk, (list, tuple)):
                    pk_list = pk
                else:
                    pk_list = [pk]
                # sanitize pk names to those we actually have
                pk_list_quoted = []
                for p in pk_list:
                    if p not in sanitized:
                        raise ValueError(f"Primary key column {p!r} not found among parsed columns.")
                    pk_list_quoted.append(f"\"{p}\"")
                pk_clause = f", PRIMARY KEY ({', '.join(pk_list_quoted)})"
            else:
                pk_clause = ""
            create_sql = f"CREATE TABLE \"{table_name}\" ({', '.join(parts)}{pk_clause});"
            cur.execute(create_sql)
            conn.commit()
        else:
            # table exists and we're appending; check columns
            cur.execute(f"PRAGMA table_info(\"{table_name}\");")
            existing_info = cur.fetchall()  # cid, name, type, notnull, dflt_value, pk
            existing_cols = [row[1] for row in existing_info]
            # Add any missing columns (as TEXT) to existing table
            for name in sanitized:
                if name not in existing_cols:
                    alter_sql = f"ALTER TABLE \"{table_name}\" ADD COLUMN \"{name}\" TEXT;"
                    cur.execute(alter_sql)
            conn.commit()
            # update col_types to include any existing column types? We'll keep our inferred types for insertion

        # Prepare insert statement
        placeholders = ", ".join(["?"] * len(sanitized))
        cols_quoted = ", ".join([f"\"{c}\"" for c in sanitized])
        insert_sql = f"INSERT INTO \"{table_name}\" ({cols_quoted}) VALUES ({placeholders});"

        # Convert rows to appropriate Python types (int, float, None, or str)
        param_rows = []
        for r in rows:
            pr = []
            for i, v in enumerate(r):
                s = v.strip() if isinstance(v, str) else (v if v is not None else "")
                if s == "":
                    pr.append(None)
                    continue
                if col_types[i] == "INTEGER":
                    iv = _try_int(s)
                    pr.append(iv if iv is not None else s)
                elif col_types[i] == "REAL":
                    fv = _try_float(s)
                    if fv is not None:
                        pr.append(fv)
                    else:
                        # maybe integer-like or text
                        iv = _try_int(s)
                        pr.append(iv if iv is not None else s)
                else:
                    pr.append(s)
            param_rows.append(tuple(pr))

        # Insert rows in a transaction
        inserted = 0
        if param_rows:
            cur.execute("BEGIN")
            try:
                cur.executemany(insert_sql, param_rows)
                inserted = cur.rowcount if cur.rowcount != -1 else len(param_rows)
                conn.commit()
            except Exception:
                conn.rollback()
                raise

        # final column list with types
        cols_with_types = list(zip(sanitized, col_types))

        return {"table": table_name, "columns": cols_with_types, "rows_inserted": inserted}
    finally:
        cur.close()
        conn.close()

Here's a single self-contained Python function that opens an image, runs OCR using pytesseract, converts the resulting text to a requested encoding, and — if OCR yields nothing useful — falls back to reading image comments/EXIF UserComment and decodes them (with a charset-detection fallback). It uses Pillow, pytesseract and chardet.

Notes:
- You must have Tesseract OCR installed on your system for pytesseract to work (e.g., brew install tesseract, apt install tesseract-ocr, or Windows installer).
- Install Python packages: pip install pillow pytesseract chardet

Function:

```python
from typing import Tuple, Optional, Dict, Any
from PIL import Image
import pytesseract
import chardet

def extract_text_from_image(
    image_path: str,
    target_encoding: str = 'utf-8',
    ocr_lang: Optional[str] = None,
    ocr_config: str = '',
    min_ocr_length: int = 5
) -> Dict[str, Any]:
    """
    Open an image, attempt to extract text via OCR, convert to target encoding,
    and if OCR fails (or is too short), fall back to image comments / EXIF UserComment.

    Returns a dict with:
      - text: the extracted Unicode string (decoded)
      - bytes: the text encoded to `target_encoding` (bytes)
      - encoding: the target_encoding used
      - source: 'ocr' or 'comment' depending on where the text came from
      - raw_ocr: raw OCR string (may be empty)
      - raw_comment: raw extracted comment (may be empty)

    Parameters:
      - image_path: path to the image file
      - target_encoding: final byte encoding to produce (default 'utf-8')
      - ocr_lang: optional language code for pytesseract (e.g. 'eng', 'jpn')
      - ocr_config: additional pytesseract config string
      - min_ocr_length: minimum length of OCR result to accept before falling back
    """

    def decode_bytes_with_chardet(b: bytes, fallback: str = 'utf-8') -> str:
        if not b:
            return ''
        det = chardet.detect(b)
        enc = det.get('encoding') or fallback
        try:
            return b.decode(enc, errors='replace')
        except Exception:
            return b.decode(fallback, errors='replace')

    def extract_comment(img: Image.Image) -> str:
        # Try EXIF UserComment (tag 37510) if available
        try:
            exif = img.getexif()
        except Exception:
            exif = None

        if exif:
            user_comment = exif.get(37510)
            if user_comment:
                # Some implementations include a 8-byte encoding prefix
                if isinstance(user_comment, bytes):
                    prefix = user_comment[:8]
                    body = user_comment[8:]
                    # Common EXIF prefixes: ASCII\0\0\0, Unicode\0, JIS\0...
                    if prefix.startswith(b'ASCII'):
                        try:
                            return body.decode('ascii', errors='replace')
                        except Exception:
                            return decode_bytes_with_chardet(user_comment)
                    if prefix.lower().startswith(b'unicode'):
                        # EXIF Unicode usually means UTF-16
                        try:
                            return body.decode('utf-16', errors='replace')
                        except Exception:
                            return decode_bytes_with_chardet(user_comment)
                    if prefix.startswith(b'JIS'):
                        try:
                            return body.decode('shift_jis', errors='replace')
                        except Exception:
                            return decode_bytes_with_chardet(user_comment)
                    # Unknown prefix -> try detection
                    return decode_bytes_with_chardet(user_comment)
                else:
                    # Already a string
                    return str(user_comment)

        # Look for common comment/text keys in image.info (PNG tEXt, JPEG comment, etc.)
        info_keys = ('comment', 'Comment', 'description', 'Description', 'ImageDescription', 'UserComment', 'text')
        for k in info_keys:
            if k in img.info:
                val = img.info[k]
                if isinstance(val, bytes):
                    return decode_bytes_with_chardet(val)
                else:
                    return str(val)

        # Some PNGs store text in a dict accessible via img.info['text'] or as individual keys
        textdict = img.info.get('text') if 'text' in img.info else None
        if isinstance(textdict, dict):
            # return combined values
            joined = '\n'.join(str(v) for v in textdict.values() if v)
            if joined:
                return joined

        return ''

    # Open image
    img = Image.open(image_path)

    # 1) Try OCR
    raw_ocr = ''
    try:
        if ocr_lang:
            raw_ocr = pytesseract.image_to_string(img, lang=ocr_lang, config=ocr_config)
        else:
            raw_ocr = pytesseract.image_to_string(img, config=ocr_config)
    except Exception:
        # OCR failed (maybe tesseract not installed). We'll fall back to comments.
        raw_ocr = ''

    raw_ocr = raw_ocr.strip() if raw_ocr else ''

    # Decide whether to use OCR or fallback comment
    use_ocr = bool(raw_ocr) and len(raw_ocr) >= (min_ocr_length or 0)

    raw_comment = ''
    if not use_ocr:
        raw_comment = extract_comment(img) or ''
        raw_comment = raw_comment.strip()

    if use_ocr:
        unicode_text = raw_ocr
        source = 'ocr'
    else:
        unicode_text = raw_comment
        source = 'comment'

    # If we still have nothing, return empty result
    if not unicode_text:
        return {
            'text': '',
            'bytes': b'',
            'encoding': target_encoding,
            'source': 'none',
            'raw_ocr': raw_ocr,
            'raw_comment': raw_comment,
        }

    # Convert to target encoding bytes (errors replaced)
    try:
        encoded_bytes = unicode_text.encode(target_encoding, errors='replace')
    except Exception:
        # fallback to utf-8 if target_encoding is invalid
        encoded_bytes = unicode_text.encode('utf-8', errors='replace')
        target_encoding = 'utf-8'

    return {
        'text': unicode_text,
        'bytes': encoded_bytes,
        'encoding': target_encoding,
        'source': source,
        'raw_ocr': raw_ocr,
        'raw_comment': raw_comment,
    }
```

Example usage:
- extract_text_from_image("invoice.jpg", target_encoding="utf-8", ocr_lang="eng")
- The returned dict contains both the Unicode text and the bytes in the requested encoding.

If you want a version that only returns the encoded bytes or only the string, you can easily adjust the return values.

from typing import Optional, Tuple
import warnings

def extract_text_from_image(
    image_path: str,
    ocr_lang: str = "eng",
    target_encoding: str = "utf-8",
    return_bytes: bool = False,
) -> Optional[bytes or str]:
    """
    Open an image file, extract text using OCR (pytesseract). If OCR produces no usable text,
    fall back to reading image comment/metadata and detect/convert its encoding using chardet.

    Dependencies (must be installed separately):
    - Pillow (PIL): pip install pillow
    - pytesseract: pip install pytesseract  (also requires the tesseract binary installed)
    - chardet: pip install chardet

    Parameters:
    - image_path: path to the image file.
    - ocr_lang: language code(s) for pytesseract (default "eng").
    - target_encoding: encoding to convert the extracted text into (default "utf-8").
    - return_bytes: if True, return bytes encoded with target_encoding; otherwise return a Python str.

    Returns:
    - Extracted text as str (default) or bytes (if return_bytes=True).
    - Returns None if no text could be extracted and no comment metadata found.

    Example:
    text = extract_text_from_image("photo.jpg")
    text_bytes = extract_text_from_image("photo.jpg", return_bytes=True)
    """
    # Imported here to keep function self-contained for copy-paste usage
    try:
        from PIL import Image, ExifTags
    except Exception as e:
        raise ImportError("Pillow is required: pip install pillow") from e
    try:
        import pytesseract
    except Exception as e:
        raise ImportError("pytesseract is required: pip install pytesseract") from e
    try:
        import chardet
    except Exception as e:
        raise ImportError("chardet is required: pip install chardet") from e
    import unicodedata

    def _normalize_unicode(s: str) -> str:
        return unicodedata.normalize("NFC", s)

    def _bytes_to_unicode(b: bytes) -> str:
        # Detect encoding using chardet, fall back sensibly
        if not b:
            return ""
        det = chardet.detect(b)
        enc = det.get("encoding")
        # If chardet is unsure, try common encodings
        tried = []
        if enc:
            try:
                return _normalize_unicode(b.decode(enc, errors="replace"))
            except Exception:
                tried.append(enc)
        for candidate in ("utf-8", "utf-16", "utf-16le", "utf-16be", "iso-8859-1", "cp1252"):
            if candidate in tried:
                continue
            try:
                return _normalize_unicode(b.decode(candidate, errors="replace"))
            except Exception:
                pass
        # Last resort: latin1 decode (guaranteed to succeed)
        return _normalize_unicode(b.decode("latin1", errors="replace"))

    # Open image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise IOError(f"Cannot open image {image_path}: {e}") from e

    # 1) Try OCR
    ocr_text = ""
    try:
        # pytesseract returns a Python str (unicode in Py3)
        ocr_text = pytesseract.image_to_string(img, lang=ocr_lang) or ""
        ocr_text = _normalize_unicode(ocr_text).strip()
    except Exception as e:
        # If pytesseract isn't configured properly or Tesseract binary missing, warn and continue to fallback
        warnings.warn(f"pytesseract OCR failed: {e}. Falling back to image comment processing.", RuntimeWarning)
        ocr_text = ""

    if ocr_text:
        # Convert to requested encoding (returns bytes if return_bytes True)
        if return_bytes:
            return ocr_text.encode(target_encoding, errors="replace")
        return ocr_text

    # 2) Fallback: try to read image comment/metadata
    comment_text = ""

    # a) Try info dict (PNG tEXt, JPEG comments, etc.)
    info = getattr(img, "info", {}) or {}
    # Many images store textual metadata in info. Try to extract anything that looks like a comment.
    # Prefer binary-like values (bytes) first so we can detect encoding; if values are str, use directly.
    candidate_values = []
    for k, v in info.items():
        # skip technical entries
        if k.lower() in ("icc_profile", "gamma", "transparency", "background"):
            continue
        if v:
            candidate_values.append((k, v))

    # b) Try EXIF UserComment (JPEG/TIFF)
    try:
        exif = img.getexif()  # returns an Exif object (mapping), or empty if none
        if exif:
            # 37510 is the UserComment tag in EXIF
            USER_COMMENT_TAG = 37510
            if USER_COMMENT_TAG in exif:
                uc = exif.get(USER_COMMENT_TAG)
                # uc may be bytes or ascii-like bytes with a charset header
                if uc:
                    candidate_values.insert(0, ("exif_user_comment", uc))
    except Exception:
        # Some formats/Pillow versions may not support getexif; ignore errors
        pass

    # c) JPEG-specific info: 'comment' key is sometimes bytes or list
    if "comment" in info and info["comment"]:
        candidate_values.insert(0, ("jpeg_comment", info["comment"]))

    # d) If PIL exposes text chunks for PNG as a dict under 'text' or similar, handle common patterns
    # (Pillow usually maps tEXt chunks into info keys directly.)
    # candidate_values is a list of tuples (key, value)
    for k, v in candidate_values:
        if isinstance(v, bytes):
            # direct bytes: try detection
            comment_text = _bytes_to_unicode(v)
            if comment_text:
                break
        elif isinstance(v, (list, tuple)):
            # e.g., JPEG may give list of comment bytes
            for item in v:
                if isinstance(item, bytes):
                    comment_text = _bytes_to_unicode(item)
                elif isinstance(item, str):
                    comment_text = _normalize_unicode(item)
                if comment_text:
                    break
            if comment_text:
                break
        elif isinstance(v, str):
            # already a unicode string (likely decoded by Pillow)
            comment_text = _normalize_unicode(v)
            if comment_text:
                break
        else:
            # Some exotic types; try to coerce to str then treat as unicode
            try:
                sv = str(v)
                comment_text = _normalize_unicode(sv)
                if comment_text:
                    break
            except Exception:
                continue

    # e) Final fallback: if nothing found, return None
    if not comment_text:
        return None

    # Return as requested
    if return_bytes:
        return comment_text.encode(target_encoding, errors="replace")
    return comment_text

