Here's a single self-contained Python function that extracts URLs from a string, derives each domain (handling subdomains and public suffixes correctly with tldextract), and queries the IP-API (http://ip-api.com/) for geolocation data. It uses the external libraries "requests" and "tldextract".

Requirements:
- pip install requests tldextract

Function:

```python
def extract_domains_geolocate(text: str, timeout: float = 5.0):
    """
    Extract URLs and domains from `text`, then query ip-api.com for geolocation info
    for each domain (or IP). Returns a dict:
      {
        "urls": [list of extracted URLs],
        "domains": {
           "example.com": { <ip-api response dict or error dict> },
           "93.184.216.34": { ... }
        }
      }

    Requires: requests, tldextract
    Install: pip install requests tldextract
    """
    import re
    import socket
    import urllib.parse
    try:
        import requests
        import tldextract
    except ImportError as ie:
        raise ImportError("Missing dependency. Install with: pip install requests tldextract") from ie

    # 1) Extract probable URLs (http(s):// and www.*)
    url_pattern = re.compile(r'(?i)\b((?:https?://|http://|www\.)\S+)\b')
    raw_urls = url_pattern.findall(text)

    # Clean trailing punctuation from URLs (common in prose)
    def clean_url(u):
        return u.rstrip('.,;:!)\]\}\'"')

    urls = [clean_url(u) for u in raw_urls]

    # 2) Extract bare domain names that might not have a scheme or www.
    # Domain regex: matches domain.tld (avoids matching emails by rejecting preceding @)
    domain_pattern = re.compile(
        r'(?<!@)\b((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,})\b',
        flags=re.IGNORECASE
    )
    raw_domains = domain_pattern.findall(text)

    # Remove domains that are already present inside an extracted URL
    urls_joined = " ".join(urls)
    bare_domains = []
    for d in raw_domains:
        if d.lower() not in urls_joined.lower():  # avoid duplicates that are inside URLs
            bare_domains.append(d)

    # 3) Build a deduplicated set of 'domains' to query
    domains_set = set()

    # Helper to get registered domain (example.co.uk) or keep IP as-is
    def registered_domain_from_host(host):
        # If it's an IP address, return as-is
        if re.fullmatch(r'\d{1,3}(?:\.\d{1,3}){3}', host):
            return host
        # Use tldextract to get the registered domain (handles co.uk etc.)
        ext = tldextract.extract(host)
        reg = ext.registered_domain
        return reg or host

    # Process urls to extract host
    for u in urls:
        parsed = urllib.parse.urlparse(u if re.match(r'^[a-zA-Z]+://', u) else 'http://' + u)
        host = parsed.hostname
        if host:
            domains_set.add(registered_domain_from_host(host))

    # Add bare domains
    for d in bare_domains:
        domains_set.add(registered_domain_from_host(d))

    # Deduplicate and remove empty strings
    domains = sorted([d for d in domains_set if d])

    # 4) Query ip-api.com for each domain
    results = {}
    api_base = "http://ip-api.com/json/"

    # fields parameter to request a compact useful subset
    fields = "status,message,country,regionName,city,lat,lon,isp,org,query"

    for d in domains:
        try:
            # Query ip-api; it accepts domains or IPs directly
            resp = requests.get(api_base + urllib.parse.quote(d), params={"fields": fields}, timeout=timeout)
            # Raise for HTTP errors (4xx/5xx)
            resp.raise_for_status()
            data = resp.json()
            # Ensure JSON
            if not isinstance(data, dict):
                results[d] = {"status": "fail", "message": "Invalid JSON from IP API"}
            else:
                results[d] = data
        except requests.exceptions.RequestException as rexc:
            results[d] = {"status": "fail", "message": f"Request error: {rexc}"}
        except ValueError as jexc:
            results[d] = {"status": "fail", "message": f"JSON decode error: {jexc}"}
        except Exception as exc:
            results[d] = {"status": "fail", "message": f"Unexpected error: {exc}"}

    return {"urls": urls, "domains": results}
```

Example usage:
- Call extract_domains_geolocate(your_text)
- Inspect the returned dict: returned["urls"] lists extracted URLs; returned["domains"] maps each deduplicated domain to the ip-api response (contains fields like status, country, city, lat, lon, isp, org, query or an error message).

Notes:
- ip-api.com has usage limits for the free endpoint; for heavy use or bulk lookups, consult their docs and consider batch endpoints or a paid tier.
- The function attempts to normalize domains (removes subdomain parts using tldextract), so if you want per-subdomain IPs instead, adjust registered_domain_from_host to return the full host.

Here's a self-contained Python function that extracts all URLs from a given string, extracts the domain for each URL, and queries the IP-API (ip-api.com) to get geolocation data for each domain. It uses the external library "requests". You can install it with pip install requests.

```
import re
import urllib.parse
import requests

def geolocate_domains_from_text(text, ip_api_url='http://ip-api.com/json/{}', timeout=5):
    """
    Extracts URLs from the input text, extracts domains and queries the IP API (ip-api.com)
    for geolocation data for each domain.

    Args:
        text (str): Input text containing zero or more URLs.
        ip_api_url (str): Template URL for the IP API; must contain one '{}' for the domain.
                          Default uses http://ip-api.com/json/{} .
        timeout (int or float): Timeout for HTTP requests in seconds.

    Returns:
        dict: Mapping domain -> api_result where api_result is the parsed JSON response from the IP API
              or an error dict like {'error': 'description'} if fetching/processing failed.

    Example:
        >>> text = "Visit https://example.com/path and http://sub.domain.org:8080/test"
        >>> geolocate_domains_from_text(text)
        {
          'example.com': {...}, 
          'sub.domain.org': {...}
        }
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Basic URL-finding regex: matches scheme://... or starting with www.
    url_pattern = re.compile(r'((?:https?://|ftp://|www\.)[^\s<>"]+)', re.IGNORECASE)
    matches = url_pattern.findall(text)

    domains = set()
    for raw_url in matches:
        # Ensure parseable scheme for urls starting with "www."
        parseable = raw_url if re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*://', raw_url) else 'http://' + raw_url
        try:
            parsed = urllib.parse.urlparse(parseable)
            hostname = parsed.hostname
            if hostname:
                # Normalize (lowercase, strip trailing dot)
                hostname = hostname.lower().rstrip('.')
                domains.add(hostname)
        except Exception:
            continue

    results = {}
    if not domains:
        return results

    session = requests.Session()
    # Request a compact set of fields from ip-api to keep responses small (optional)
    fields = "status,message,country,regionName,city,lat,lon,query,isp,org,as,timezone"

    for domain in sorted(domains):
        try:
            resp = session.get(ip_api_url.format(domain), params={'fields': fields}, timeout=timeout)
            resp.raise_for_status()
            data = resp.json()
            # ip-api returns status == "success" or "fail"
            if isinstance(data, dict):
                results[domain] = data
            else:
                results[domain] = {'error': 'Unexpected non-JSON response'}
        except requests.RequestException as e:
            results[domain] = {'error': f'HTTP error: {str(e)}'}
        except ValueError:
            results[domain] = {'error': 'Invalid JSON in response'}
        except Exception as e:
            results[domain] = {'error': f'Unexpected error: {str(e)}'}

    return results
```

Notes:
- This uses ip-api.com (no API key required but subject to rate limits and terms). Change ip_api_url if you prefer another geolocation API.
- The regex finds URLs with scheme or those beginning with www. It does not detect bare domains without "www" or scheme; if you want that too, the regex can be extended.
- The returned dict contains the raw ip-api response for each domain (so you can inspect status/message/lat/lon/etc.).

import os
import json
from datetime import datetime
from typing import Optional, Any
import requests

def download_url_from_json(json_string: str, key: str, directory: Optional[str] = None) -> str:
    """
    Parse a JSON string, locate a URL associated with the specified key, download the file,
    and save it with a timestamped filename '{key}_{timestamp}.txt' where timestamp uses
    format '%Y%m%d%H%M%S%f' (microsecond precision). Returns the full path to the saved file.

    The function looks for the first occurrence of `key` anywhere in the JSON structure.
    If the value at that key is:
      - a string that starts with 'http://' or 'https://', it is treated as the URL;
      - a dict, the function will check for a 'url' entry inside that dict;
      - a list, the function will scan the list for the first string that looks like a URL.

    Parameters:
      json_string: The JSON content as a string.
      key: The key to search for in the parsed JSON.
      directory: Optional directory to save the downloaded file. If None, uses current working directory.

    Returns:
      The full path to the saved file.

    Raises:
      ValueError: if JSON is invalid, no matching key/url is found, or download fails.
      requests.RequestException: for network-related errors during download.
      OSError: for filesystem-related errors when creating directories or writing the file.
    """
    def is_url(s: Any) -> bool:
        return isinstance(s, str) and s.startswith(("http://", "https://"))

    def find_key(obj: Any, target: str) -> Optional[Any]:
        # Recursive search for key in dicts/lists. Returns the value when the key matches.
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == target:
                    return v
                res = find_key(v, target)
                if res is not None:
                    return res
        elif isinstance(obj, list):
            for item in obj:
                res = find_key(item, target)
                if res is not None:
                    return res
        return None

    # Parse JSON
    try:
        parsed = json.loads(json_string)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    found = find_key(parsed, key)
    if found is None:
        raise ValueError(f"Key '{key}' not found in the provided JSON.")

    # Derive URL from the found value
    url = None
    if is_url(found):
        url = found
    elif isinstance(found, dict) and is_url(found.get("url")):
        url = found.get("url")
    elif isinstance(found, list):
        for item in found:
            if is_url(item):
                url = item
                break
            if isinstance(item, dict) and is_url(item.get("url")):
                url = item.get("url")
                break

    if not url:
        raise ValueError(f"No URL found for key '{key}' in the JSON structure.")

    # Prepare filename and directory
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S%f")
    safe_key = str(key)
    filename = f"{safe_key}_{timestamp}.txt"
    if directory:
        os.makedirs(directory, exist_ok=True)
        out_path = os.path.join(directory, filename)
    else:
        out_path = os.path.join(os.getcwd(), filename)

    # Download the URL and write to file
    try:
        with requests.get(url, stream=True) as r:
            r.raise_for_status()
            with open(out_path, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        # Cleanup partial file if created
        if os.path.exists(out_path):
            try:
                os.remove(out_path)
            except Exception:
                pass
        raise

    return out_path

